import heapq

def dijkstra(graph, start):
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    pq = [(0, start)]
    while pq:
        cur_d, u = heapq.heappop(pq)
        if cur_d > distances[u]: continue
        for v, weight in graph[u].items():
            dist = cur_d + weight
            if dist < distances[v]:
                distances[v] = dist
                heapq.heappush(pq, (dist, v))
    return distances

import heapq

def a_star(graph, start, goal, heuristic):
    pq = [(heuristic(start, goal), 0, start, [start])]
    visited = set()
    while pq:
        f, g, cur, path = heapq.heappop(pq)
        if cur == goal: return path, g
        if cur in visited: continue
        visited.add(cur)
        for neighbor, cost in graph[cur]:
            if neighbor not in visited:
                new_g = g + cost
                heapq.heappush(pq, (new_g + heuristic(neighbor, goal), new_g, neighbor, path + [neighbor]))
    return None, float('inf')

from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity: int):
        self.cap = capacity
        self.cache = OrderedDict()
    def get(self, key):
        if key not in self.cache: return -1
        self.cache.move_to_end(key)
        return self.cache[key]
    def put(self, key, value):
        if key in self.cache: self.cache.move_to_end(key)
        self.cache[key] = value
        if len(self.cache) > self.cap:
            self.cache.popitem(last=False)

from collections import deque

def topological_sort(num_nodes, edges):
    in_degree = {i: 0 for i in range(num_nodes)}
    adj = {i: [] for i in range(num_nodes)}
    for u, v in edges:
        adj[u].append(v)
        in_degree[v] += 1
    q = deque([n for n in in_degree if in_degree[n] == 0])
    order = []
    while q:
        node = q.popleft()
        order.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                q.append(neighbor)
    return order if len(order) == num_nodes else None

def levenshtein_distance(s1: str, s2: str) -> int:
    if len(s1) < len(s2): s1, s2 = s2, s1
    prev = list(range(len(s2) + 1))
    for i, c1 in enumerate(s1):
        curr = [i + 1] * (len(s2) + 1)
        for j, c2 in enumerate(s2):
            curr[j + 1] = prev[j] if c1 == c2 else 1 + min(prev[j + 1], curr[j], prev[j])
        prev = curr
    return prev[-1]

import hashlib, bisect

class ConsistentHashRing:
    def __init__(self, replicas=100):
        self.replicas = replicas
        self.ring = []
        self.node_map = {}
    def _hash(self, key):
        return int(hashlib.md5(key.encode('utf-8')).hexdigest(), 16)
    def add_node(self, node):
        for i in range(self.replicas):
            h = self._hash(f'{node}:{i}')
            bisect.insort(self.ring, h)
            self.node_map[h] = node
    def get_node(self, key):
        if not self.ring: return None
        h = self._hash(key)
        idx = bisect.bisect_right(self.ring, h)
        if idx == len(self.ring): idx = 0
        return self.node_map[self.ring[idx]]
